WITH filtered AS (SELECT id, brand, price, cost, launch_date, tags, supplier_id, ADD_MONTHS(launch_date, 1) AS launch_date_plus_months FROM products WHERE supplier_id IS NOT NULL) SELECT id, brand, tags, launch_date_plus_months, LAST_VALUE(price) IGNORE NULLS OVER (PARTITION BY brand ORDER BY launch_date_plus_months, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_price, MAX(cost) OVER (PARTITION BY supplier_id) AS supplier_id_max_cost, AVG(price) OVER (ORDER BY price, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS price_avg_3_prior, NTILE(4) OVER (PARTITION BY supplier_id ORDER BY cost DESC, id) AS cost_bucket, ROW_NUMBER() OVER (PARTITION BY supplier_id, brand ORDER BY price DESC, id) AS event_seq FROM filtered WHERE cost < 720
